import React, { useState, useEffect } from "react";
import "../styles/CreateArticlesAdmin.css";
import { contentFactory } from "../contentFactory";

function CreateArticlePage() {
  const [mode, setMode] = useState("article");
  const [articleData, setArticleData] = useState({
    title: "",
    slug: "",
    content: "",
    excerpt: "",
    status: "draft",
    type: "standard",
    category: "sport",
    is_premium: false,
    image: null,
    author: "",
  });
  const [pollQuestion, setPollQuestion] = useState("");
  const [pollOptions, setPollOptions] = useState(["", ""]);
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedAuthor, setSelectedAuthor] = useState("");

  const token = localStorage.getItem("token");

  useEffect(() => {
    // Завантажуємо канали
    const fetchChannels = async () => {
      try {
        const res = await fetch("http://127.0.0.1:8000/api/channels/", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json();
        setChannels(Array.isArray(data) ? data : data.results || []);
      } catch (err) {
        console.error("Не вдалося завантажити канали:", err);
      }
    };

    // Завантажуємо користувачів для вибору автора
    const fetchUsers = async () => {
      try {
        const res = await fetch("http://127.0.0.1:8000/api/users/", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json();
        setUsers(Array.isArray(data) ? data : data.results || []);
      } catch (err) {
        console.error("Не вдалося завантажити користувачів:", err);
      }
    };

    fetchChannels();
    fetchUsers();
  }, [token]);

  const handleArticleChange = (e) => {
    const { name, value, type, checked, files } = e.target;
    setArticleData({
      ...articleData,
      [name]: type === "checkbox" ? checked : type === "file" ? files[0] : value,
    });
  };

  const handleOptionChange = (index, value) => {
    const updated = [...pollOptions];
    updated[index] = value;
    setPollOptions(updated);
  };

  const addOption = () => setPollOptions([...pollOptions, ""]);
  const removeOption = (index) => setPollOptions(pollOptions.filter((_, i) => i !== index));

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const factory = contentFactory(mode, token);

      if (mode === "article") {
        await factory({ ...articleData, author: selectedAuthor || null });
        alert("✅ Статтю створено!");
      } else {
        const filteredOptions = pollOptions.filter((o) => o.trim() !== "");
        if (!pollQuestion.trim() || filteredOptions.length < 2) {
          alert("Опитування має містити питання і мінімум два варіанти");
          return;
        }
        await factory({
          question: pollQuestion,
          options: filteredOptions,
          channel: selectedChannel || null,
          is_premium: articleData.is_premium,
          author: selectedAuthor || null,
        });
        alert("✅ Опитування створено!");
      }

      window.location.href = "/";
    } catch (err) {
      alert(`❌ Помилка: ${err.message}`);
      console.error(err);
    }
  };

  return (
    <div className="create-article-container">
      <h2>Створення контенту</h2>

      <div className="mode-switch">
        <button onClick={() => setMode("article")} className={mode === "article" ? "active" : ""}>
          📰 Стаття
        </button>
        <button onClick={() => setMode("poll")} className={mode === "poll" ? "active" : ""}>
          📊 Опитування
        </button>
      </div>

      <form onSubmit={handleSubmit} className="create-article-form">
        <label>Автор:</label>
            <select
              name="author"
              value={articleData.author || ""}
              onChange={(e) => setArticleData({ ...articleData, author: e.target.value })}
            >
              <option value="">-- Виберіть автора --</option>
              {users.map((u) => (
                <option key={u.id} value={u.id}>{u.username}</option>
              ))}
            </select>

        {mode === "article" ? (
          <>
            <input type="text" name="title" placeholder="Заголовок" value={articleData.title} onChange={handleArticleChange} required />
            <input type="text" name="slug" placeholder="Slug" value={articleData.slug} onChange={handleArticleChange} required />
            <textarea name="content" placeholder="Основний текст" rows="6" value={articleData.content} onChange={handleArticleChange} required />
            <textarea name="excerpt" placeholder="Короткий опис" rows="3" value={articleData.excerpt} onChange={handleArticleChange} />
            <select name="category" value={articleData.category} onChange={handleArticleChange}>
              <option value="sport">Спорт</option>
              <option value="fashion">Мода</option>
              <option value="News">Новини</option>
            </select>
            <label>
              <input type="checkbox" name="is_premium" checked={articleData.is_premium} onChange={handleArticleChange} />
              Преміум стаття
            </label>
            <input type="file" name="image" accept="image/*" onChange={handleArticleChange} />
          </>
        ) : (
          <>
            <input type="text" placeholder="Питання" value={pollQuestion} onChange={(e) => setPollQuestion(e.target.value)} required />
            <select value={selectedChannel} onChange={(e) => setSelectedChannel(e.target.value)}>
              <option value="">-- Виберіть канал --</option>
              {channels.map((ch) => (
                <option key={ch.id} value={ch.id}>{ch.name}</option>
              ))}
            </select>
            {pollOptions.map((opt, idx) => (
              <div key={idx}>
                <input type="text" value={opt} onChange={(e) => handleOptionChange(idx, e.target.value)} placeholder={`Варіант ${idx + 1}`} />
                {pollOptions.length > 2 && <button type="button" onClick={() => removeOption(idx)}>✖</button>}
              </div>
            ))}
            <button type="button" onClick={addOption}>➕ Додати варіант</button>
          </>
        )}
        <button type="submit" className="create-article-button">
          {mode === "article" ? "Створити статтю" : "Створити опитування"}
        </button>
      </form>
    </div>
  );
}

export default CreateArticlePage;
